// Code generated by xgen. DO NOT EDIT.
// Source: xgen/screens/src/authoring/components/orders.ts
/** The orders as a table (the table layout of OrderTable): number, date, items, total and a status pill. */
import { type ReactNode } from "react";
import { Box } from "../primitives/box/box";
import { Table } from "../primitives/table/table";
import { TableBody } from "../primitives/table/table-body";
import { TableCaption } from "../primitives/table/table-caption";
import { TableCell } from "../primitives/table/table-cell";
import { TableHead } from "../primitives/table/table-head";
import { TableHeadCell } from "../primitives/table/table-head-cell";
import { TableRow } from "../primitives/table/table-row";
import { Pill } from "../components/pill";
import { at, cn, fmtMoney, tpl } from "../utils";
import type { Order, OrderLabels } from "../blocks/order-table.types";

export type OrderRowsProps = {
  orders: Order[];
  statuses: Record<string, string>;
  labels: OrderLabels;
  density?: "default" | "compact";
};

export function OrderRows({ orders, statuses, labels, density = "default" }: OrderRowsProps) {
  return (
    <Box className="w-full overflow-x-auto">
      <Table className="w-full text-left text-sm" data-testid="order-table">
        <TableCaption className="sr-only">
          {labels.caption}
        </TableCaption>
        <TableHead>
          <TableRow>
            <TableHeadCell scope="col" className="py-2">
              {labels.number}
            </TableHeadCell>
            <TableHeadCell scope="col" className="py-2">
              {labels.date}
            </TableHeadCell>
            <TableHeadCell scope="col" className="py-2">
              {labels.items}
            </TableHeadCell>
            <TableHeadCell scope="col" className="py-2">
              {labels.total}
            </TableHeadCell>
            <TableHeadCell scope="col" className="py-2">
              {labels.status}
            </TableHeadCell>
          </TableRow>
        </TableHead>
        <TableBody>
          {(orders ?? []).map((o) => (
            <TableRow key={o.id} className="border-t border-border" data-testid="item">
              <TableCell className={cn("font-semibold", (((density as string) === "compact") ? "py-2" : "py-4"))}>
                {o.number}
              </TableCell>
              <TableCell>
                {o.date}
              </TableCell>
              <TableCell>
                {tpl(labels.itemsCount, o.items)}
              </TableCell>
              <TableCell>
                {fmtMoney(o.total, o.currency)}
              </TableCell>
              <TableCell>
                <Pill
                  tone={
                    o.status === "paid" ? "green"
                    : o.status === "shipped" ? "blue"
                    : o.status === "pending" ? "amber"
                    : "gray"
                  }
                >
                  {at(statuses, o.status)}
                </Pill>
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </Box>
  );
}
